oyle to Resign as Ambassador to Greece','U.S. and Japan Hold Second Indo-Pacific Dialogue in Tokyo on Aid and Security','Saudi Engineer Charged With Planting Recording Device in OpenAI Office') and a.byline_email is not null;
    if exists (select 1 from pg_trigger where tgname = 'articles_byline_email') then
